    const auto output_dtype = GetOutputPointer<ge::DataType>(index);
    if (output_dtype == nullptr) {
      return ge::GRAPH_FAILED;
    }
    *output_dtype = datatype;
    return ge::GRAPH_SUCCESS;
  }
