    if (compute_node_info == nullptr) {
      return nullptr;
    }
    return compute_node_info->GetInputInstanceInfo(ir_index);
  }

  /**
   * 根据IR原型中的index，获取在节点上的输出实例化信息
   * @param ir_index IR原型中定义的index
   * @return 实例化信息
